/* Controlled retail script fixtures; this is not a natural ending/playthrough. */
#define main native_fixture_test_main
#include "test_party_native.c"
#undef main
#include "../src/host/restoration.h"
#include "../src/host/png.h"
#include "../src/core/sha256.h"
static const unsigned operands[]={0x15,0x16,0x74,0x75,0xaf,0xb0,0xb7,0xd7,0xe9,0xea,0x6c3c,0x6c68,0x6c69,0x6c9d,0x6c9e,0x6ca1,0x6cb1,0x7edd,0x7ede,0x7edf,0x7ee0};
typedef struct{unsigned script,phase,bank,events,frame,last_frame,last_offset;int active;bool started,done,stopped,jumped;uint64_t event_hash;cpu_t saved;uint8_t stack[2],scratch[32];} run_t;
typedef struct{unsigned pixels,frame;uint16_t original[256*240],enhanced[256*240];} capture_t;
static capture_t proof[3];
static void write_guest(nes_t*c,unsigned a,unsigned v){if(a<0x800)c->ram[a]=(uint8_t)v;else c->prgram[a-0x6000]=(uint8_t)v;}
static void script_observer(nes_t*c,void*state){run_t*s=state;
 if(c->cpu.pc==0xc429){unsigned slot=readn(c,0x6314);if(slot<20&&(readn(c,0x638d+slot)&63)==2&&readn(c,0x63a1+slot)==s->script){unsigned ptr=readn(c,0x7ede)|(readn(c,0x7edf)<<8),base=readn(c,0x6ca9)|(readn(c,0x6caa)<<8),offset=(ptr-base)&65535u;
  if(s->script==63&&offset==0x21&&!s->jumped){/* Controlled credits entry: retain original setup, skip ending plot from 0x21 to 0x268. */ptr=base+0x268;write_guest(c,0x7ede,ptr&255);write_guest(c,0x7edf,ptr>>8);offset=0x268;s->jumped=true;}
  s->events++;s->event_hash=(s->event_hash^offset)*1099511628211ULL;s->event_hash=(s->event_hash^s->frame)*1099511628211ULL;s->last_frame=s->frame;s->last_offset=offset;
  unsigned bank=readn(c,0x6cb1),opcode=c->prg[bank*16384+(ptr&16383)];if(opcode==0x14){s->active=-1;if(s->script==140&&offset==0x62)s->active=0;if(s->script==63&&offset==0x32b)s->active=1;if(s->script==63&&offset==0x3bc)s->active=2;}
 }}
 if(c->cpu.pc==0xc7e9){unsigned slot=readn(c,0x6314);if(slot<20&&readn(c,0x63a1+slot)==s->script)s->stopped=true;}
 if(s->done||c->cpu.pc!=0xc049)return;
 if(!s->started){s->started=true;s->saved=c->cpu;s->bank=(c->mmc1.prg_lo-c->prg)/16384;s->stack[0]=readn(c,0x100|c->cpu.s);s->stack[1]=readn(c,0x100|((c->cpu.s-1)&255));for(unsigned i=0;i<sizeof(operands)/sizeof(*operands);i++)s->scratch[i]=readn(c,operands[i]);}else if(c->cpu.s!=s->saved.s)return;
 unsigned pc;
 if(s->phase++==0){c->cpu.a=s->script;pc=0xc582;}else if(s->phase==2){c->cpu.a=s->bank;pc=0xdf85;}else{for(unsigned i=0;i<sizeof(operands)/sizeof(*operands);i++)write_guest(c,operands[i],s->scratch[i]);write_guest(c,0x100|s->saved.s,s->stack[0]);write_guest(c,0x100|((s->saved.s-1)&255),s->stack[1]);c->cpu.a=s->saved.a;c->cpu.x=s->saved.x;c->cpu.y=s->saved.y;c->cpu.p=s->saved.p;c->cpu.s=s->saved.s;s->done=true;return;}
 write_guest(c,0x100|c->cpu.s,0xc0);c->cpu.s--;write_guest(c,0x100|c->cpu.s,0x48);c->cpu.s--;c->cpu.pc=(uint16_t)pc;
}
static bool load_prg(nes_t*c,const uint8_t*prg,const char*fixture){nes_init(c,prg,cart.prg_size);size_t z=nes_state_size();void*b=malloc(z);FILE*f=fopen(fixture,"rb");if(!f)return false;size_t got=fread(b,1,z,f);fclose(f);bool ok=nes_state_load(c,b,got,romid);free(b);return ok;}
static void save_proof(const char*dir,unsigned which){if(!dir)return;const char*names[]={"ed","scumm","nes-scumm"};char path[1024];snprintf(path,sizeof path,"%s/%s-original.png",dir,names[which]);CHECK(png_write_nes(path,proof[which].original));snprintf(path,sizeof path,"%s/%s-enhanced.png",dir,names[which]);CHECK(png_write_nes(path,proof[which].enhanced));}
static void compare_scene(unsigned script,const uint8_t*copy,const char*fixture,const char*dir){CHECK(load_prg(&n,copy,fixture));CHECK(load_prg(&plain,cart.prg,fixture));run_t a={0},b={0};a.script=b.script=script;a.active=b.active=-1;a.event_hash=b.event_hash=1469598103934665603ULL;n.exec_hook=script_observer;n.exec_hook_ud=&a;plain.exec_hook=script_observer;plain.exec_hook_ud=&b;unsigned f;for(f=0;f<9000;f++){a.frame=b.frame=f;unsigned pad=(script==140&&f>100&&f%180<3)?PAD_A:0;nes_set_pad(&n,0,pad);nes_set_pad(&plain,0,pad);nes_run_frame(&n);nes_run_frame(&plain);if(a.active>=0&&a.active==b.active){unsigned pixels=0;for(unsigned i=0;i<256*240;i++)pixels+=n.ppu.fb[i]!=plain.ppu.fb[i];if(pixels>proof[a.active].pixels){proof[a.active].pixels=pixels;proof[a.active].frame=f;memcpy(proof[a.active].original,plain.ppu.fb,sizeof proof[a.active].original);memcpy(proof[a.active].enhanced,n.ppu.fb,sizeof proof[a.active].enhanced);}}
 if(script==140&&a.stopped&&b.stopped)break;
 if(script==63&&a.last_offset>=0x3e1&&b.last_offset>=0x3e1)break;}
 printf("CONTROLLED native script%u frames%u events%u/%u hash%llx/%llx last%04x/%04x stop%u/%u\n",script,f,a.events,b.events,(unsigned long long)a.event_hash,(unsigned long long)b.event_hash,a.last_offset,b.last_offset,a.stopped,b.stopped);CHECK(f<9000);CHECK(a.events==b.events&&a.event_hash==b.event_hash);CHECK(readn(&n,0x63c6)==readn(&plain,0x63c6));CHECK(readn(&n,0x6b08)==readn(&plain,0x6b08));CHECK(readn(&n,0x6b09)==readn(&plain,0x6b09));for(unsigned i=51;i<=54;i++){CHECK(readn(&n,0x6000+i)==readn(&plain,0x6000+i));CHECK(readn(&n,0x6100+i)==readn(&plain,0x6100+i));}for(unsigned i=1;i<=25;i++){CHECK(readn(&n,0x6b5d+i)==readn(&plain,0x6b5d+i));CHECK(readn(&n,0x6b43+i)==readn(&plain,0x6b43+i));}for(unsigned i=0;i<3;i++)if((script==140&&i==0)||(script==63&&i>0)){printf("renderproof%u pixels%u frame%u\n",i,proof[i].pixels,proof[i].frame);CHECK(proof[i].pixels>0);save_proof(dir,i);}}
int main(int argc,char**argv){if(argc<3||argc>4)return 2;setvbuf(stdout,NULL,_IOLBF,0);char err[512];if(!cart_load(&cart,argv[1],false,err,sizeof err))return 2;for(unsigned i=0;i<8;i++){unsigned v;sscanf(cart.prg_sha256+2*i,"%2x",&v);romid[i]=v;}uint8_t*copy=malloc(cart.prg_size);if(!copy)return 2;memcpy(copy,cart.prg,cart.prg_size);CHECK(restoration_apply(copy,cart.prg_size,false,(restoration_options_t){true,true})==RESTORATION_OFF);CHECK(!memcmp(copy,cart.prg,cart.prg_size));CHECK(load_prg(&n,copy,argv[2]));CHECK(load_prg(&plain,cart.prg,argv[2]));for(unsigned i=0;i<900;i++){unsigned pad=i%120<15?PAD_RIGHT:0;nes_set_pad(&n,0,pad);nes_set_pad(&plain,0,pad);nes_run_frame(&n);nes_run_frame(&plain);CHECK(same(&n,&plain));}printf("Original stale restorationALLON:900 exact native snapshots\n");CHECK(restoration_apply(copy,cart.prg_size,true,(restoration_options_t){true,true})==RESTORATION_APPLIED);bool outside_unchanged=true;for(size_t i=0;i<cart.prg_size;i++){bool span=(i>=0x26ef7&&i<0x26efc)||(i>=0x233f0&&i<0x233f5)||(i>=0x23487&&i<0x2348e);if(!span&&copy[i]!=cart.prg[i])outside_unchanged=false;}CHECK(outside_unchanged);compare_scene(140,copy,argv[2],argc==4?argv[3]:NULL);compare_scene(63,copy,argv[2],argc==4?argv[3]:NULL);char digest[65];sha256_hex(cart.prg,cart.prg_size,digest);CHECK(!strcmp(digest,cart.prg_sha256));printf("restoration native checks%u failures%u immutable-owner-PRG=yes\n",checks,failures);free(copy);cart_free(&cart);return failures?1:0;}
